export function calculateInvoiceTotal(items) {
  const subtotal = items.reduce((s, i) => s + i.price * i.qty, 0);
  return subtotal + subtotal * 0.08;
}

export function calculateOrderTotal(orderLines) {
  const subtotal = orderLines.reduce((s, l) => s + l.unitPrice * l.count, 0);
  return subtotal + subtotal * 0.08;
}

export function getDiscountForUser(user) {
  const base = user.loyaltyLevel > 3 ? 0.1 : 0.05;
  return base + (user.vip ? 0.02 : 0);
}

export function getDiscountForOrder(order) {
  const base = order.customer.loyaltyLevel > 3 ? 0.1 : 0.05;
  return base + (order.isVip ? 0.02 : 0);
}

/* Version A */
export function computeFee(amount: number, opts: { rounding: 'up' | 'down' }) {
  const base = Math.floor(amount * 100) / 100;
  return opts.rounding === 'up' ? Math.ceil(base) : Math.floor(base);
}

/* Version B */
export class BillingHelper {
  static roundUp(inCents: number) { return Math.ceil(inCents / 100); }
  static roundDown(inCents: number) { return Math.floor(inCents / 100); }
}

// ServiceA uses BillingHelper.roundUp and accesses cents conversion directly
// ServiceB uses BillingHelper.roundDown and duplicates cents conversion logic
